css:
/* Oro vitrin sayfaları: kronoloji, sözlük, kitaplar */
html { scroll-behavior: smooth; }
body.page-id-958, body.page-id-960, body.page-id-962 { background-color: #17110b; color: #eadfc8; }
.page-id-958 .wp-block-site-title a, .page-id-960 .wp-block-site-title a, .page-id-962 .wp-block-site-title a,
.page-id-958 .wp-block-navigation a, .page-id-960 .wp-block-navigation a, .page-id-962 .wp-block-navigation a,
.page-id-958 .wp-block-site-title, .page-id-960 .wp-block-site-title, .page-id-962 .wp-block-site-title { color: #eadfc8 !important; }
.page-id-958 .wp-block-social-link svg, .page-id-960 .wp-block-social-link svg, .page-id-962 .wp-block-social-link svg { fill: #d9a93a !important; color: #d9a93a !important; }
.page-id-958 .wp-block-post-content, .page-id-960 .wp-block-post-content, .page-id-962 .wp-block-post-content { max-width: none !important; }
.oro-hero { padding: 4rem 1rem !important; text-align: center; }
.oro-hero h1 { color: #f3d27a; font-size: clamp(2.6rem, 7vw, 5rem); margin: 0 0 1rem; letter-spacing: .02em; }
.oro-alinti { font-style: italic; font-size: 1.3rem; line-height: 1.5; color: #f1e7d3; max-width: 640px; margin-left: auto !important; margin-right: auto !important; }
.oro-kaynak { color: #d9a93a; font-size: 1rem; letter-spacing: .08em; }
.oro-yolbar { position: sticky; top: 0; z-index: 20; background: rgba(23,17,11,.94); border-top: 1px solid #5a4322; border-bottom: 1px solid #5a4322; margin: 0 !important; }
.admin-bar .oro-yolbar { top: 32px; }
.oro-yolbar-ic { display: flex; gap: 1.4rem; justify-content: safe center; overflow-x: auto; white-space: nowrap; padding: .75rem 1rem; margin: 0 !important; scrollbar-width: none; }
.oro-yolbar-ic::-webkit-scrollbar { display: none; }
.oro-yolbar-ic a { color: #eadfc8; text-decoration: none; font-size: 1rem; letter-spacing: .06em; padding-bottom: .15rem; border-bottom: 2px solid transparent; }
.oro-yolbar-ic a:hover { color: #f3d27a; border-bottom-color: #d9a93a; }
.oro-bant { padding: 3.5rem 1rem !important; margin: 0 !important; }
.oro-bant h2 { scroll-margin-top: 90px; color: #f3d27a; font-size: clamp(1.8rem, 4vw, 2.6rem); margin: 0 0 .6rem; }
.oro-ic { max-width: 1240px; margin: 0 auto; }
.oro-giris { max-width: 720px; font-size: 1.2rem; line-height: 1.6; margin: 0 0 1.6rem !important; color: #eadfc8; }
.oro-koyu { background: #0f0b07; }
.oro-kan { background: linear-gradient(180deg, #2a0f0c, #17110b); }
.oro-ray { display: flex !important; gap: 1.1rem; overflow-x: auto; scroll-snap-type: x mandatory; padding: .4rem .2rem 1.2rem; scrollbar-width: auto; scrollbar-color: #d9a93a #33261a; }
.oro-ray::-webkit-scrollbar { height: 14px; }
.oro-ray::-webkit-scrollbar-track { background: #33261a; border-radius: 8px; border: 4px solid #17110b; }
.oro-ray::-webkit-scrollbar-thumb { background: linear-gradient(90deg, #8a6420, #f3d27a, #8a6420); border-radius: 8px; }
.oro-ray > * { margin: 0 !important; max-width: none !important; }
.oro-kart { flex: 0 0 min(76vw, 290px); scroll-snap-align: start; background: #241a10; border: 1px solid #5a4322; border-radius: 4px; overflow: hidden; display: flex; flex-direction: column; transition: transform .25s ease, border-color .25s ease; }
.oro-kart:hover { transform: translateY(-5px); border-color: #d9a93a; }
.oro-kart figure { margin: 0 !important; }
.oro-kart img { width: 100%; height: 200px; object-fit: cover; display: block; }
.oro-cilt { flex-basis: min(66vw, 240px); }
.oro-cilt img { height: 320px; object-fit: contain; background: #0f0b07; padding: .5rem; box-sizing: border-box; }
.oro-kart-metin { padding: .9rem 1rem 1.1rem; }
.oro-kart-metin > * { margin-top: 0 !important; }
.oro-kart h3 { font-size: 1.2rem; margin: 0 0 .4rem; color: #f1e7d3; line-height: 1.25; }
.oro-kart h3 a, .oro-bant h3 a { color: inherit; text-decoration: none; font-size: inherit; }
.oro-kart h3 a:hover { color: #f3d27a; }
.oro-kart p { font-size: 1.02rem; line-height: 1.45; margin: 0; color: #e0d3b8; }
.oro-etiket { color: #d9a93a !important; font-size: .82rem !important; letter-spacing: .1em; text-transform: uppercase; margin: 0 0 .35rem !important; }
.oro-mevsim { color: #c9b58f; font-style: italic; font-size: 1rem; }
.oro-ipucu { color: #a8926c; font-size: .9rem; margin: .2rem 0 0 !important; }
.oro-sifir { display: grid; grid-template-columns: 1fr auto 1fr; gap: .5rem 1.5rem; align-items: center; max-width: 820px; margin: 0 auto; text-align: center; }
.oro-sifir > * { margin: 0 !important; }
.oro-sifir-a { font-family: var(--wp--preset--font-family--arvo); font-size: 1.5rem; color: #d9a93a; }
.oro-sifir-b { font-family: var(--wp--preset--font-family--arvo); font-size: 1.15rem; color: #17110b; background: #d9a93a; padding: .35rem 1rem; border-radius: 3px; }
.oro-sifir-m { grid-column: 1 / -1; font-size: 1.15rem; line-height: 1.6; margin-top: .8rem !important; }
.oro-aylar { display: flex; justify-content: center; margin: 1rem 0 2rem; }
.oro-ay { width: 110px; height: 110px; border-radius: 50%; margin: 0 !important; }
.oro-sedef { background: radial-gradient(circle at 35% 30%, #fff8ea, #cfc3ad 60%, #7d7263); box-shadow: 0 0 30px rgba(240,230,210,.45); }
.oro-kanli { background: radial-gradient(circle at 35% 30%, #e0604a, #8e1c14 60%, #3f0a07); box-shadow: 0 0 30px rgba(190,40,25,.5); margin-left: -28px !important; mix-blend-mode: screen; }
.oro-takvim { display: grid; grid-template-columns: repeat(5, 1fr); gap: .8rem; }
.oro-takvim > * { margin: 0 !important; }
.oro-ayfasil { background: #241a10; border-top: 3px solid #d9a93a; padding: .9rem 1rem; }
.oro-ayfasil:nth-child(1) { border-top-color: #8fb7c4; } .oro-ayfasil:nth-child(2) { border-top-color: #6f9a4b; } .oro-ayfasil:nth-child(4) { border-top-color: #b8552a; } .oro-ayfasil:nth-child(5) { border-top-color: #cfc3ad; }
.oro-ayfasil h3 { color: #f3d27a; font-size: 1.25rem; margin: 0 0 .2rem; }
.oro-ayfasil p { margin: 0 0 .4rem; font-size: 1.02rem; line-height: 1.4; }
.oro-alfabe { display: flex; flex-wrap: wrap; gap: .35rem; margin: 0 0 1.6rem !important; }
.oro-alfabe a { display: inline-block; min-width: 2.2rem; text-align: center; padding: .3rem .2rem; background: #241a10; border: 1px solid #5a4322; color: #f3d27a; text-decoration: none; font-family: var(--wp--preset--font-family--arvo); font-size: 1.05rem; }
.oro-alfabe a:hover { background: #d9a93a; color: #17110b; }
.oro-lugat { columns: 2; column-gap: 2.5rem; }
.oro-harfgrup { break-inside: avoid; margin: 0 0 1.4rem !important; }
.oro-harf { color: #d9a93a; font-size: 1.7rem; margin: 0 0 .4rem; scroll-margin-top: 90px; border-bottom: 1px solid #5a4322; }
.oro-lugat details { padding: .4rem 0; border-bottom: 1px dotted #4a3820; margin: 0 !important; }
.oro-lugat summary { cursor: pointer; font-size: 1.15rem; color: #f1e7d3; }
.oro-lugat summary:hover { color: #f3d27a; }
.oro-lugat details p { font-size: 1.08rem; line-height: 1.5; margin: .4rem 0 .3rem 1rem; color: #d8c9ab; }
.oro-vitrin { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: 2.5rem; align-items: center; }
.oro-ters { grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); }
.oro-vitrin > * { margin: 0 !important; max-width: none !important; }
.oro-vitrin figure img { width: 100%; height: auto; border: 1px solid #5a4322; display: block; }
.oro-vitrin-m > * { max-width: none !important; }
.oro-vitrin-m p { font-size: 1.15rem; line-height: 1.6; }
.oro-satin { gap: .6rem; margin: 1.2rem 0 .6rem !important; }
.oro-satin .wp-block-button__link { background: #d9a93a; color: #17110b; border-radius: 3px; padding: .55rem 1.1rem; font-size: 1.05rem; text-decoration: none; }
.oro-satin .wp-block-button__link:hover { background: #f3d27a; }
.oro-raf { color: #f1e7d3; margin: 1.8rem 0 .6rem; font-size: 1.4rem; }
.oro-raf a { text-decoration: none; }
@media (max-width: 782px) {
	.admin-bar .oro-yolbar { top: 46px; }
	.oro-yolbar-ic { justify-content: flex-start; }
	.oro-takvim { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }
	.oro-ayfasil { flex: 0 0 70vw; scroll-snap-align: start; }
	.oro-lugat { columns: 1; }
	.oro-vitrin, .oro-ters { grid-template-columns: 1fr; gap: 1.5rem; }
	.oro-ters figure { order: -1; }
	.oro-bant { padding: 2.5rem 1rem !important; }
}
@media (prefers-reduced-motion: reduce) {
	html { scroll-behavior: auto; }
	.oro-kart { transition: none; }
}
